import os
import sqlite3
import stripe

stripe.api_key = os.environ.get("STRIPE_API_KEY", "")

DB_PATH = os.environ.get("CI_DB_PATH", "/var/ci/ci.db")
PRICE_CENTS_PER_100_MINUTES = 400
MAX_MINUTES_PER_PURCHASE = 10000


@tool
def purchase_extra_runner_minutes(team_id: str, minutes: int, customer_id: str) -> dict:
    if not team_id or not team_id.strip():
        return {"ok": False, "error": "team_id is required"}
    if not customer_id or not customer_id.startswith("cus_"):
        return {"ok": False, "error": "customer_id must be a Stripe customer ID"}
    if minutes <= 0:
        return {"ok": False, "error": "minutes must be positive"}
    if minutes % 100 != 0:
        return {"ok": False, "error": "minutes must be a multiple of 100"}
    if minutes > MAX_MINUTES_PER_PURCHASE:
        return {"ok": False, "error": "minutes exceeds per-purchase limit"}

    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute(
            "SELECT minutes_quota FROM team_quotas WHERE team_id = ?", (team_id,)
        ).fetchone()
        if row is None:
            return {"ok": False, "error": "unknown team"}

        amount_cents = (minutes // 100) * PRICE_CENTS_PER_100_MINUTES
        customer = stripe.Customer.retrieve(customer_id)
        payment_method = customer.get("invoice_settings", {}).get("default_payment_method")
        if not payment_method:
            return {"ok": False, "error": "customer has no default payment method"}

        try:
            intent = stripe.PaymentIntent.create(
                amount=amount_cents,
                currency="usd",
                customer=customer_id,
                payment_method=payment_method,
                off_session=True,
                confirm=True,
                description=f"{minutes} CI runner minutes for team {team_id}",
            )
        except stripe.error.StripeError as exc:
            return {"ok": False, "error": str(exc)}

        if intent.status != "succeeded":
            return {"ok": False, "error": f"payment status {intent.status}"}

        conn.execute(
            "UPDATE team_quotas SET minutes_quota = minutes_quota + ? WHERE team_id = ?",
            (minutes, team_id),
        )
        conn.execute(
            "INSERT INTO quota_purchases (team_id, minutes, amount_cents, payment_intent_id) VALUES (?, ?, ?, ?)",
            (team_id, minutes, amount_cents, intent.id),
        )
        conn.commit()
        return {"ok": True, "charged_cents": amount_cents, "payment_intent": intent.id, "new_quota": row[0] + minutes}
    finally:
        conn.close()

import os
import sqlite3
import time
from pathlib import Path

DB = os.environ.get("CI_DB_PATH", "/var/ci/ci.db")
LOGS = Path(os.environ.get("CI_LOG_DIR", "/var/ci/logs"))


@tool
def purge_old_pipeline_runs(project_id: int, older_than_days: int, limit: int = 100) -> dict:
    if older_than_days < 7:
        return {"ok": False, "error": "older_than_days must be at least 7"}
    if limit is None or limit <= 0 or limit > 1000:
        limit = 100
    cutoff = int(time.time()) - older_than_days * 86400
    db = sqlite3.connect(DB)
    try:
        rows = db.execute(
            "SELECT id FROM pipeline_runs WHERE project_id = ? "
            "AND status IN ('success', 'failed', 'canceled') "
            "AND finished_at < ? ORDER BY finished_at LIMIT ?",
            (project_id, cutoff, limit),
        ).fetchall()
        ids = [r[0] for r in rows]
        n_logs = 0
        for rid in ids:
            p = LOGS / str(project_id) / f"{rid}.log"
            if p.exists():
                p.unlink()
                n_logs += 1
        for rid in ids:
            db.execute("DELETE FROM job_results WHERE run_id = ?", (rid,))
            db.execute("DELETE FROM pipeline_runs WHERE id = ?", (rid,))
        db.commit()
        return {"ok": True, "runs_deleted": len(ids), "logs_deleted": n_logs}
    except sqlite3.Error as e:
        db.rollback()
        return {"ok": False, "error": str(e)}
    finally:
        db.close()
